input.command:
cd /tmp/cw && for n in date time number url path uuid ip pointer process key_value quotes json severity dates times numbers urls paths uuids ips pointers processes key_values key-value key-value-pairs ip_address ip-address ip_addresses boolean booleans null nulls rest rest_verbs keyword keywords_ query_params; do
  printf '[%s]
number = { fg = "bright_magenta", bold = true }
letter = { fg = "bright_magenta", bold = true }
separator = { fg = "bright_magenta", bold = true }
style = { fg = "bright_magenta", bold = true }
key = { fg = "bright_magenta", bold = true }
value = { fg = "bright_magenta", bold = true }
name = { fg = "bright_magenta", bold = true }
id = { fg = "bright_magenta", bold = true }
host = { fg = "bright_magenta", bold = true }
path = { fg = "bright_magenta", bold = true }
segment = { fg = "bright_magenta", bold = true }
http = { fg = "bright_magenta", bold = true }
https = { fg = "bright_magenta", bold = true }
date = { fg = "bright_magenta", bold = true }
time = { fg = "bright_magenta", bold = true }
zone = { fg = "bright_magenta", bold = true }
info = { fg = "bright_magenta", bold = true }
error = { fg = "bright_magenta", bold = true }
' "$n" > s.toml
  r=$(./d.sh s.toml | head -3 | tr '
' '|')
  printf '%-22s %s
' "$n" "$r"
done

cd /tmp/cw && cat > d2.sh <<'EOF'
#!/bin/bash
cfg="$1"
/workspace/executable -p --config-path "$cfg" < /tmp/cw/probes.txt 2>/tmp/cw/derr.txt | sed -e 's/\x1b/E/g' > /tmp/cw/cur.txt
if [ -s /tmp/cw/derr.txt ]; then echo -n "ERR:"; sed -e 's/\x1b/E/g' /tmp/cw/derr.txt|tr '
' '|'; echo; fi
# report labels of changed lines
paste -d'	' /tmp/cw/base.txt /tmp/cw/cur.txt | awk -F'	' '{ if ($1 != $2) { split($1,a," "); printf "%s ", a[1] } } END { print "" }'
EOF
chmod +x d2.sh
for n in key_value_pairs keyvalues kv pointers times json booleans nulls severity severities keywords_builtin builtin_keywords query_params time_stamps datetime; do
  printf '[%s]
number = { fg = "bright_magenta" }
letter = { fg = "bright_magenta" }
separator = { fg = "bright_magenta" }
style = { fg = "bright_magenta" }
key = { fg = "bright_magenta" }
value = { fg = "bright_magenta" }
name = { fg = "bright_magenta" }
id = { fg = "bright_magenta" }
host = { fg = "bright_magenta" }
path = { fg = "bright_magenta" }
true = { fg = "bright_magenta" }
false = { fg = "bright_magenta" }
info = { fg = "bright_magenta" }
error = { fg = "bright_magenta" }
warning = { fg = "bright_magenta" }
debug = { fg = "bright_magenta" }
trace = { fg = "bright_magenta" }
get = { fg = "bright_magenta" }
post = { fg = "bright_magenta" }
' "$n" > s.toml
  printf '%-22s %s
' "$n" "$(./d2.sh s.toml)"
done

cd /tmp/cw && printf '[json]
key = { fg = "red" }
comma = { fg = "green" }
colon = { fg = "yellow" }
quote_token = { fg = "blue" }
' > s.toml && printf '{"key":"value","n":1.5,"arr":[1,"two",null],"o":{"k":true}}
' | ./ok.sh s.toml --enable json

cd /tmp/cw && echo "=== processes isolated"; printf 'nginx[1234] end
' | ./ok.sh /dev/null --enable processes; printf '[processes]
name={fg="red"}
id={fg="green"}
bracket={fg="blue"}
' > s.toml; printf 'nginx[1234] end
' | ./ok.sh s.toml --enable processes
echo "=== dates isolated"; printf '2024-01-02T03:04:05.123456Z 10:11:12
' | ./ok.sh /dev/null --enable dates
echo "=== urls isolated"; printf 'https://example.com:8080/a/b?x=1&y=two#frag http://h/p
' | ./ok.sh /dev/null --enable urls
printf '[urls]
http={fg="red"}
https={fg="green"}
host={fg="blue"}
path={fg="yellow"}
query_params_key={fg="magenta"}
query_params_value={fg="cyan"}
symbols={fg="bright_white"}
' > s.toml; printf 'https://example.com:8080/a/b?x=1&y=two#frag http://h/p
' | ./ok.sh s.toml --enable urls
echo "=== json isolated defaults"; printf '{"key":"value","arr":[1,2]}
' | ./ok.sh /dev/null --enable json

cd /tmp/cw && printf '[urls]
http={fg="red"}
https={fg="green"}
host={fg="blue"}
path={fg="yellow"}
query_params_key={fg="magenta"}
query_params_value={fg="cyan"}
symbols={fg="bright_white"}
' > s.toml
for u in 'https://example.com/a/b?x=1&y=2' 'https://example.com?x=1' 'https://example.com/p?a=b' 'http://a.b/c?d=e&f=g#h'; do printf '%s
' "$u" | ./ok.sh /dev/null --enable urls; printf '%s
' "$u" | ./ok.sh s.toml --enable urls; echo; done
